	public static void main(String[] args) {
		StringBuilder sb = new StringBuilder();
		java.util.Map<String, String> qp = new java.util.TreeMap<>();
		qp.put("includeObjectsInProtocol", "false");
		RESTWrapper rw = new RESTWrapper();
		RequestHandler rh = new RequestHandler( new org.json.JSONArray().put(new org.json.JSONObject().put("identifier", "StandardizationValue.Value")), 1000, request -> {
			rw.writeData("list", "StandardizationValue", null, qp, request, System.out::println);
		} );
		qp.clear();
		qp.put("fields", 
				  "StandardizationValue.StructureGroup->LookupValue.Code"
				+ ",StandardizationValue.Characteristic->Characteristic.Identifier"
				+ ",StandardizationValue.CreationType->LookupValue.Code"
				+ ",StandardizationValue.Property->LookupValue.Code"
			);
		qp.put("dictionary", "ExtensionDeMetadatos_ ValoresPredeterminadosPorPlantilla");
		for(int i=0; i<IDS.length; i++) {
			sb.append(sb.length() == 0 ? "" : ",");
			sb.append("'");
			sb.append(IDS[i]);
			sb.append("'@'ExtensionDeMetadatos_ ValoresPredeterminadosPorPlantilla'");
			if((i+1) % 50 == 0) {
				qp.put("items", sb.toString());
				rw.collectData("list", "StandardizationValue", null, "byItems", qp, row -> {
					org.json.JSONArray values = row.getJSONArray("values");
					rh.addRow(new org.json.JSONObject().put("object", row.getJSONObject("object")).put("values", new org.json.JSONArray().put( values.getString(0) + "<::>" + values.getString(1) + "<::>" + values.getString(2) + "<::>" + values.getString(3))));
				});
				sb.setLength(0);
			}
		}
		qp.put("dictionary", "ExtensionDeMetadatos_ ValoresPredeterminadosPorPlantilla");
		qp.put("items", sb.toString());
		rw.collectData("list", "StandardizationValue", null, "byItems", qp, row -> {
			org.json.JSONArray values = row.getJSONArray("values");
			rh.addRow(new org.json.JSONObject().put("object", row.getJSONObject("object")).put("values", new org.json.JSONArray().put( values.getString(0) + "<::>" + values.getString(1) + "<::>" + values.getString(2) + "<::>" + values.getString(3))));
		});
		rh.sendData();
	}
	
